mapper.select:
select 


order by ep.evaluation_year desc, ep.teacher_user_id, ep.area_code, ep.target_function_code, ep.exception_start_at desc
limit #{criteria.safeSize} offset #{criteria.offset}

select count(*)
from exception_period_settings ep
where ep.active_yn = 'Y'
  and ep.evaluation_year = #{evaluationYear}
  and ep.teacher_user_id = #{teacherUserId}
  and ep.area_code = #{areaCode}
  and ep.target_function_code = #{targetFunctionCode}
  and tsrange(ep.exception_start_at, ep.exception_end_at, '[]') && tsrange(#{exceptionStartAt}, #{exceptionEndAt}, '[]')

      and ep.setting_id != #{settingId}

select count(*)
from (
    select ea.area_code
    from evaluation_areas ea
    where ea.area_code = #{areaCode}
      and ea.active_yn = 'Y'
    union
    select mp.area_code
    from modification_period_settings mp
    where mp.area_code = #{areaCode}
      and mp.active_yn = 'Y'
) areas

select 

where ep.active_yn = 'Y'
  and ep.teacher_user_id = #{teacherUserId}
  and ep.area_code = #{areaCode}
  and ep.target_function_code = #{targetFunctionCode}
  and ep.exception_start_at <= #{requestAt}
  and ep.exception_end_at >= #{requestAt}
order by ep.exception_start_at desc
limit 1

select count(*)
from modification_period_settings mp
where mp.active_yn = 'Y'
  and mp.evaluation_year = #{evaluationYear}
  and mp.start_at <= #{requestAt}
  and mp.end_at >= #{requestAt}

      and mp.area_code = #{areaCode}


      and mp.organization_code = #{organizationCode}
